<?php
require_once dirname(__DIR__).'/app/init.php';require_once dirname(__DIR__).'/app/layout.php';$pdo=db();$items=cart_items($pdo);if(!$items)go('/cart.php');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$phone=trim((string)($_POST['phone']??''));$city=trim((string)($_POST['city']??''));$address=trim((string)($_POST['address']??''));$notes=trim((string)($_POST['notes']??''));
 if($name===''||mb_strlen($name)>120)$errors[]=t('name');if(!preg_match('/^[0-9+().\s-]{8,30}$/',$phone))$errors[]=t('phone');if($city===''||mb_strlen($city)>100)$errors[]=t('city');if($address===''||mb_strlen($address)>255)$errors[]=t('address');if(mb_strlen($notes)>1000)$errors[]=t('notes');
 if(!$errors){try{$pdo->beginTransaction();$locked=[];$total=0;$cart=$_SESSION['cart']??[];foreach($cart as $pid=>$qty){if(!ctype_digit((string)$pid))continue;$qty=max(1,min(99,(int)$qty));$stmt=$pdo->prepare("SELECT id,name_ar,name_fr,price,stock FROM products WHERE id=? AND is_active=1 FOR UPDATE");$stmt->execute([(int)$pid]);$p=$stmt->fetch();if(!$p||(int)$p['stock']<$qty)throw new RuntimeException(t('low_stock'));$p['qty']=$qty;$p['line_total']=(float)$p['price']*$qty;$total+=$p['line_total'];$locked[]=$p;}if(!$locked)throw new RuntimeException(t('empty'));
 $number='NOVA-'.strtoupper(bin2hex(random_bytes(4)));$uid=current_user()['id']??null;$stmt=$pdo->prepare("INSERT INTO orders(user_id,order_number,customer_name,phone,address,city,notes,total_amount) VALUES(?,?,?,?,?,?,?,?)");$stmt->execute([$uid,$number,$name,$phone,$address,$city,$notes,$total]);$orderId=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?)");$upd=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");
 foreach($locked as $p){$label=(($_SESSION['lang']??'ar')==='fr')?$p['name_fr']:$p['name_ar'];$ins->execute([$orderId,$p['id'],$label,$p['price'],$p['qty'],$p['line_total']]);$upd->execute([$p['qty'],$p['id'],$p['qty']]);if($upd->rowCount()!==1)throw new RuntimeException(t('low_stock'));}
 $pdo->commit();$_SESSION['cart']=[];$_SESSION['order_success']=$number;go('/order-success.php');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():t('error');}}}
$total=array_sum(array_column($items,'line_total'));page_header(t('checkout'));?>
<h1 class="page-title"><?=h(t('checkout'))?></h1><?php if($errors):?><div class="flash"><?=h(implode(' · ',$errors))?></div><?php endif;?>
<div class="cart-layout"><form method="post" class="panel stack"><?=csrf_field()?><div class="form-grid">
<?php foreach(['name','phone','city','address','notes'] as $field):?><div class="form-group <?=in_array($field,['address','notes'],true)?'full':''?>"><label><?=h(t($field))?></label><?php if($field==='notes'):?><textarea class="field" name="notes" maxlength="1000"><?=h($_POST['notes']??'')?></textarea><?php else:?><input class="field" name="<?=h($field)?>" maxlength="<?= $field==='address'?255:120 ?>" required value="<?=h($_POST[$field]??($field==='name'?(current_user()['name']??''):''))?>"><?php endif;?></div><?php endforeach;?></div><p class="muted"><?=h(t('cod'))?></p><button class="btn" type="submit"><?=h(t('place_order'))?></button></form><aside class="panel"><h2><?=h(t('total'))?></h2><?php foreach($items as $p):?><div class="summary-line"><span><?=h(product_name($p))?> × <?=$p['qty']?></span><b><?=h(cash($p['line_total']))?></b></div><?php endforeach;?><div class="summary-line"><b><?=h(t('total'))?></b><b class="summary-total"><?=h(cash($total))?></b></div></aside></div>
<?php page_footer();?>
